corrected_code:
const express = require('express');
const { trace } = require('@opentelemetry/api');

const app = express();
const deploymentSpanStore = new Map();

app.get('/api/traces/deployments/:deploymentSpanId', (req, res) => {
  if (!req.user || !req.user.repositoryIds) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const span = deploymentSpanStore.get(req.params.deploymentSpanId);
  if (!span) {
    return res.status(404).json({ error: 'Deployment span not found' });
  }

  const repoId = span.attributes['ci.repository_id'];
  // Verify user has read access to the deployed repository
  if (!req.user.repositoryIds.includes(repoId)) {
    return res.status(403).json({ error: 'Forbidden: no permission to inspect repository deployment trace' });
  }

  // Redact sensitive environment variables
  const safeEnvVars = { ...span.attributes['ci.staging_env_vars'] };
  delete safeEnvVars.DATABASE_URL;
  delete safeEnvVars.DEPLOY_KEY;

  res.json({
    deploymentSpanId: req.params.deploymentSpanId,
    dockerImage: span.attributes['ci.docker_image'],
    gitCommit: span.attributes['ci.git_commit_sha'],
    stagingEnvVars: safeEnvVars
  });
});

app.listen(4043);
